function validate(input) {
  const [{ Person = [], Country = [], Calls = [] }] = input;
  const codes = new Set(), names = new Set(), people = new Set();
  for (const [name, code] of Country) {
    if (code === null || !/^\d{3}$/.test(code)) return 'Every country_code has exactly 3 digits.';
    if (codes.has(code)) return `country_code ${code} appears twice in Country.`;
    if (name === null || names.has(name)) return 'Every country needs a unique name.';
    codes.add(code); names.add(name);
  }
  for (const [id, , phone] of Person) {
    if (id === null || people.has(id)) return 'Every person needs a unique id.';
    people.add(id);
    if (phone === null || !/^\d{3}-\d{7}$/.test(phone)) return `Person ${id}'s phone_number must look like 051-1234567.`;
    if (!codes.has(phone.slice(0, 3))) return `Person ${id}'s country code is not in Country.`;
  }
  for (const [caller, callee, duration] of Calls) {
    if (!people.has(caller) || !people.has(callee)) return 'Every caller and callee must be in Person.';
    if (caller === callee) return 'A person cannot call themselves.';
    if (duration === null || duration < 0) return 'Every duration must be a non-negative number.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const digits = n => Array.from({ length: n }, () => Math.floor(rand() * 10)).join('');
  let Country, people, calls, durations;
  if (size === 'small') {
    const pool = [['Peru', '051'], ['Israel', '972'], ['Morocco', '212'], ['Germany', '049'], ['Ethiopia', '251']];
    Country = pool.filter(() => rand() < 0.6);
    if (!Country.length) Country = [pool[Math.floor(rand() * pool.length)]];
    people = Math.floor(rand() * 7);
    calls = people >= 2 ? Math.floor(rand() * 9) : 0;
    durations = [1, 5, 10, 20, 30, 60];
  } else {
    Country = Array.from({ length: 12 }, (_, i) => [`Country${i + 1}`, String(100 + i * 7).padStart(3, '0')]);
    people = 400; calls = 2000;
    durations = Array.from({ length: 120 }, (_, i) => i + 1);
  }
  const names = ['Jonathan', 'Elvis', 'Moncef', 'Maroua', 'Meir', 'Rachel', 'Ana', 'Ben'];
  const Person = [];
  for (let id = 1; id <= people; id++) Person.push([id, pick(names), `${pick(Country)[1]}-${digits(7)}`]);
  const Calls = [];
  for (let i = 0; i < calls; i++) {
    // Repeat the previous call now and then: Calls has no key.
    if (Calls.length && rand() < 0.15) { Calls.push([...Calls[Calls.length - 1]]); continue; }
    const caller = 1 + Math.floor(rand() * people);
    let callee = 1 + Math.floor(rand() * (people - 1));
    if (callee >= caller) callee++;
    Calls.push([caller, callee, pick(durations)]);
  }
  return [{ Person, Country, Calls }];
}
